<?php
namespace OpenLMS\Controllers;

use OpenLMS\Core\Auth;
use OpenLMS\Core\Csrf;
use OpenLMS\Core\Database;
use OpenLMS\Policies\CoursePolicy;
use OpenLMS\Services\UploadService;

trait ProjectViewTrait
{
    public static function view(): void
    {
        require_feature('projects');Auth::requireAuth();$u=Auth::user();$pdo=Database::connection();$id=(int)($_GET['id']??0);$p=self::project($id);if(!$p||!self::canView($p,$u)){http_response_code(404);render_page('Not found','<div class="card">Project unavailable.</div>');return;}$canManage=CoursePolicy::canManage($p,$u)&&Auth::can('projects.manage');$error=null;$message=null;
        if($_SERVER['REQUEST_METHOD']==='POST'){
            if(!Csrf::validate($_POST['_csrf']??null))$error='Security token expired.';else try{$action=(string)($_POST['action']??'');
                if($action==='publish'&&$canManage){$oldStatus=$p['status'];$status=in_array($_POST['status']??'draft',['draft','published','archived'],true)?$_POST['status']:'draft';$pdo->prepare('UPDATE projects SET status=?,updated_at=? WHERE id=?')->execute([$status,gmdate('Y-m-d H:i:s'),$id]);$p['status']=$status;if($status==='published'&&$oldStatus!=='published')notify_course_students((int)$p['course_id'],'New project: '.$p['title'],'A new project or assignment is available in '.$p['course_title'].'.','project',app_url('?r=project&id='.$id));$message='Project status updated.';}
                elseif($action==='create_group'&&$canManage){if($p['project_type']!=='group')throw new \RuntimeException('This is not a group project.');$name=trim((string)($_POST['group_name']??''));if($name==='')throw new \RuntimeException('Group name is required.');$pdo->prepare('INSERT INTO project_groups (project_id,name,created_by,created_at) VALUES (?,?,?,?)')->execute([$id,$name,(int)$u['id'],gmdate('Y-m-d H:i:s')]);$message='Group created.';}
                elseif($action==='add_group_member'&&$canManage){$gid=(int)($_POST['group_id']??0);$sid=(int)($_POST['student_id']??0);if(!self::groupBelongs($gid,$id)||!self::studentHasCourse($sid,(int)$p['course_id']))throw new \RuntimeException('Invalid group membership.');$pdo->prepare('DELETE FROM project_group_members WHERE user_id=? AND group_id IN (SELECT id FROM project_groups WHERE project_id=?)')->execute([$sid,$id]);$pdo->prepare('INSERT INTO project_group_members (group_id,user_id) VALUES (?,?)')->execute([$gid,$sid]);$message='Group member assigned.';}
                elseif($action==='submit'&&!$canManage){self::submitProject($p,$u);$message='Submission uploaded.';}
                elseif($action==='grade'&&$canManage){$sub=self::submission((int)($_POST['submission_id']??0));if(!$sub||(int)$sub['project_id']!==$id)throw new \RuntimeException('Submission unavailable.');$marks=max(0,min((float)$p['max_marks'],(float)($_POST['marks']??0)));$feedback=mb_substr(trim((string)($_POST['feedback']??'')),0,5000);$pdo->prepare("UPDATE project_submissions SET marks=?,feedback=?,graded_by=?,graded_at=?,status='graded',rubric_scores_json=? WHERE id=?")->execute([$marks,$feedback,(int)$u['id'],gmdate('Y-m-d H:i:s'),trim((string)($_POST['rubric_scores_json']??'')),(int)$sub['id']]);self::upsertGrade($sub,$p,$marks,(int)$u['id']);$notifyIds=[(int)$sub['user_id']];if(!empty($sub['group_id'])){$gm=$pdo->prepare('SELECT user_id FROM project_group_members WHERE group_id=?');$gm->execute([(int)$sub['group_id']]);$notifyIds=array_values(array_unique(array_merge($notifyIds,array_map('intval',$gm->fetchAll(\PDO::FETCH_COLUMN)))));}foreach($notifyIds as $uid)notify_user($uid,'Project graded: '.$p['title'],'Your project grade is available: '.$marks.' / '.$p['max_marks'].'.','project',app_url('?r=project&id='.$id));$message='Submission graded.';}
            }catch(\Throwable $e){$error=$e instanceof \RuntimeException?$e->getMessage():'Unable to update project.';}}
        $groups=self::groups($id);$students=$canManage?self::courseStudents((int)$p['course_id']):[];$subs=self::submissionsForProject($p,$u,$canManage);ob_start();?><div class="page-head"><div><h1><?=e($p['title'])?></h1><p class="muted"><?=e($p['course_title'])?> · <?=e($p['project_type'])?> · Deadline <?=e($p['deadline_at']??'none')?></p></div><a class="btn" href="<?=e(app_url('?r=projects'))?>">Back</a></div><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><section class="card"><p><?=nl2br(e((string)$p['instructions']))?></p><p class="muted">Allowed: <?=e($p['allowed_extensions'])?> · Max <?=round((int)$p['max_upload_bytes']/1048576,1)?> MB · Late: <?=e($p['late_policy'])?> · Resubmission: <?=(int)$p['resubmission_allowed']?'yes':'no'?></p><?php if($canManage):?><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="publish"><select name="status"><option>draft</option><option>published</option><option>archived</option></select><button class="btn">Update status</button></form><?php endif;?></section>
        <?php if($canManage&&$p['project_type']==='group'):?><section class="card"><h2>Groups</h2><div class="grid-2"><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="create_group"><label>Group name<input name="group_name" required></label><button class="btn">Create group</button></form><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="add_group_member"><label>Group<select name="group_id"><?php foreach($groups as $g):?><option value="<?=(int)$g['id']?>"><?=e($g['name'])?></option><?php endforeach;?></select></label><label>Student<select name="student_id"><?php foreach($students as $s):?><option value="<?=(int)$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></label><button class="btn">Assign member</button></form></div><div class="compact-list"><?php foreach($groups as $g):?><div><span><strong><?=e($g['name'])?></strong><small><?=e($g['members']?:'No members')?></small></span></div><?php endforeach;?></div></section><?php endif;?>
        <?php if(!$canManage&&$p['status']==='published'):?><section class="card"><h2>Submit work</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="submit"><label>Files<input type="file" name="files[]" <?= (int)$p['allow_multiple_files']?'multiple':'' ?> required></label><button class="btn btn-primary">Submit new version</button></form></section><?php endif;?>
        <section class="card table-card"><h2>Submissions</h2><div class="table-scroll"><table><thead><tr><th>Owner</th><th>Version</th><th>Status</th><th>Submitted</th><th>Files</th><th>Grade</th></tr></thead><tbody><?php foreach($subs as $s):?><tr><td><?=e($s['owner_name'])?><small><?=e($s['group_name']??'')?></small></td><td>v<?=(int)$s['version_no']?> <?= (int)$s['is_late']?'<span class="badge badge-warn">Late</span>':'' ?></td><td><?=e($s['status'])?></td><td><?=e($s['submitted_at']??'—')?></td><td><?php foreach(self::submissionFiles((int)$s['id']) as $f):?><a href="<?=e(app_url('?r=project-file&id='.(int)$f['id']))?>"><?=e($f['original_name'])?></a><br><?php endforeach;?></td><td><?php if($canManage):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="grade"><input type="hidden" name="submission_id" value="<?=(int)$s['id']?>"><input type="number" name="marks" min="0" max="<?=e($p['max_marks'])?>" step="0.25" value="<?=e($s['marks']??0)?>"><input name="feedback" placeholder="Feedback" value="<?=e($s['feedback']??'')?>"><input name="rubric_scores_json" placeholder="Rubric scores JSON" value="<?=e($s['rubric_scores_json']??'')?>"><button class="btn btn-small">Grade</button></form><?php else:?><?=e($s['marks']??'Pending')?><?=!empty($s['feedback'])?'<small>'.e($s['feedback']).'</small>':''?><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php render_page('Project',ob_get_clean());
    }
}
